    /**
     * Tests getting all Pharmacys.
     *
     * @return    Collection
     */
    public List<Pharmacy> testGetAll() throws Throwable {
    LOGGER.info( "PharmacyTest:testGetAll() - Retrieving Collection of Pharmacys:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Pharmacy : " );
    List<Pharmacy> collection  = null;

    try {
        // call the static get method on the PharmacyService
        collection = service.getAllPharmacy();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Pharmacy currEntity  = null;
            Iterator<Pharmacy> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPharmacyId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

